  UPDATE yj_std_lib SET content = N'{"v":1,"rows":[{"工序":"无黑处理","工序控制内容":"无黑处理时间","管控要求":"1. 将炭棒单层摆车无黑处理，破损、裂纹等不良挑出\n2. 无黑处理时间：12-24小时","检查比例":"随机取2支测试黑水"},{"工序":"机器除尘","工序控制内容":"1.机器毛刷松紧度\n2.除尘后清洁效果","管控要求":"1.炭棒内外壁毛刷清洁除尘一次\n2.除尘后用气枪吹内孔及表面一次","检查比例":"3%"},{"工序":"气枪吹灰","工序控制内容":"1.炭棒表面吹灰\n2.炭棒内孔吹灰","管控要求":"气枪吹内孔及表面一次","检查比例":"3%"},{"工序":"投首","工序控制内容":"1.炭棒尺寸：长度、内径、外径\n2.炭棒外观：表面、脱粉、强度","管控要求":"1尺寸在规格内，外径：59.3-60.3mm，内径：39.3-40.3mm\n长度：129.3-120.3mm\n2.炭棒无破损、无压痕，无裂纹\n3.脱粉检查方法;用搓三次炭棒表面后，无炭粉脱落为合格\n4.强度：用手捏炭棒切口，无捏碎、捏裂及疏松为合格","检查比例":"尺寸：3%\n外观：3%"},{"工序":"机器包布","工序控制内容":"1. 无纺布封口质量\n2. 布裹炭棒松紧度\n3. 两端炭棒外露长度","管控要求":"1. 无纺布封口熔接牢固，无开裂及把布熔化现象，接口用手扣不开为合格\n2. 无纺布须裹紧炭棒，捏炭棒一端，布甩不脱掉为合格\n3. 两端炭棒外露长度为5-8mm(用钢尺测量）","检查比例":"10%"},{"工序":"放内布","工序控制内容":"1. 无纺布尺寸\n2. 无纺布外观","管控要求":"1. 内布、折叠棉（翻棉）长度与炭棒长度一致，布接口用热熔胶粘住","检查比例":"全检"},{"工序":"包布/套网","工序控制内容":"1.. 无纺布、网尺寸\n2. 无纺布、网外观","管控要求":"布和网无褶皱，套上后长度与炭棒一致","检查比例":"全检"},{"工序":"套折叠棉/扎橡皮筋","工序控制内容":"1. 成品长\n2. 外径\n3. 折叠棉品质（折数，外径）","管控要求":"1. 成品长120±0.5mm\n2. 成品外径：71.7±0.5mm\n3. 折数：145±10折","检查比例":"尺寸：1%\n折数：1%\n外观：全检"},{"工序":"套PP棉","工序控制内容":"1. PP棉外观\n2. PP棉尺寸","管控要求":"1. 检查PP棉无破损、脏污等不良\n2. PP棉长度与炭棒长度一致","检查比例":"全检"},{"工序":"粘端盖","工序控制内容":"1. 胶位\n2. 胶量\n3. 成品长度\n4. 粘接歪斜","管控要求":"1.点胶机温度：180±10度\n2.胶量:2.5±0.5g\n3.成品长度：508±0.5mm\n4.检查整个炭棒切面须有胶水粘附\n5.放台面比较，无歪斜（倾斜度不大于0.5mm)","检查比例":"1.尺寸：1%\n2.胶位：1%\n3.外观：3%"},{"工序":"装垫片","工序控制内容":"1. 垫片外观\n2. 漏装","管控要求":"1. 无脏污、破损\n2. 无漏装","检查比例":"全检"},{"工序":"外观检查","工序控制内容":"脏污/漏部件/歪斜","管控要求":"检查产品无脏污、溢胶、头发丝等卫生问题，无漏垫片，无歪斜（斜面不大于0.5mm）","检查比例":"全检"},{"工序":"装袋/封口","工序控制内容":"1. 漏部件\n2. 卫生问题\n3. 塑封袋封切质量","管控要求":"1. 无漏部件，无头发丝，飞虫、脏污\n2. 塑封袋封切无破洞、褶皱","检查比例":"全检"},{"工序":"塑封","工序控制内容":"1..塑封机参数\n2.塑封质量","管控要求":"1.塑封温度：120-150度\n2.塑封无褶皱、破洞","检查比例":"全检"},{"工序":"外观检查（两端及端盖LOGO)","工序控制内容":"1. 塑封质量\n2. 漏部件、混料\n3. 卫生问题","管控要求":"1. 塑封无破洞、褶皱\n2. 无漏装垫片、端盖无混LOGO\n3. 无脏污、头发丝、蚊虫等","检查比例":"全检"},{"工序":"贴标签","工序控制内容":"1.标签内容\n2.标签位置","管控要求":"在产品约中间部位贴一标签，标签无歪斜，无褶皱，边角无翘起（内容与具体位置参照样品）","检查比例":"全检"},{"工序":"外观检查(侧面）","工序控制内容":"4. 塑封质量\n5. 漏部件\n6. 卫生问题","管控要求":"4. 塑封无破洞、褶皱\n5. 检查标签无翘起，无漏贴标签\n6. 无脏污、头发丝、蚊虫等","检查比例":"全检"},{"工序":"装箱","工序控制内容":"装箱方式/数量","管控要求":"准备好纸箱，套一PE袋，折好刀卡，将外观合格的产品竖放在纸箱内，具体方法：每格1支，每排3支，装6排，每箱装18支，然后用扎带扎口，封箱方式为”工“字形","检查比例":"全检"}]}', seq = 40, enabled = 1,
