SELECT lib_code, item_code, seq, enabled, LEN(content) AS content_len
FROM yj_std_lib WHERE lib_code = N'asm.proc' ORDER BY seq;
GO

IF (SELECT COUNT(*) FROM yj_std_lib WHERE lib_code = N'asm.proc') <> 4
  PRINT N'⚠⚠ asm.proc 条目数不为 4:库里混进了乱码变体,标准库选择框会把它们列出来,需人工删除'
ELSE
  PRINT N'OK  asm.proc 恰好 4 个变体,无乱码孪生条目';
GO

